	r.tree.Insert(s, v)
	return v, true
}

func (r *NodeShiftTree[T]) InsertRawWithLock(s string, v any) (any, bool) {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.tree.Insert(s, v)
}

func (r *NodeShiftTree[T]) InsertWithLock(s string, v T) (T, bool) {
	r.mu.Lock()
